INSERT INTO `movies` (`row_key`, `id`, `title`, `slug`, `status`, `release_date`, `ord`, `data`, `updated_at`) VALUES
('1#0', '1', 'Hai Phượng', 'hai-phuong', 'now_showing', '2026-10-11', 0, '{\"title\":\"Hai Phượng\",\"slug\":\"hai-phuong\",\"tagline\":\"Một người mẹ, một mình chống cả thế giới.\",\"description\":\"Hai Phượng kể về hành trình đầy gay cấn của người mẹ vùng quê tìm cách cứu con khỏi đường dây bắt cóc khổng lồ. Không một tấc sắt trong tay, người phụ nữ thân cô thế cô phải chống lại bọn xã hội đen tàn ác để giành lại nguồn sống của đời mình.\",\"director\":\"Lê Văn Kiệt\",\"cast\":[\"Ngô Thanh Vân\",\"Phan Thanh Nhiên\",\"Phạm Anh Khoa\",\"Thanh Hoa\",\"Mai Cát Vi\"],\"genres\":[\"Hành động\",\"Võ thuật\",\"Giật gân\",\"Chính kịch\"],\"duration\":100,\"releaseDate\":\"2026-10-11\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":6.6,\"status\":\"now_showing\",\"featured\":true,\"art\":{\"from\":\"#f97316\",\"via\":\"#7c2d12\",\"to\":\"#0c0a09\",\"accent\":\"#fed7aa\"},\"posterUrl\":\"/posters/hai-phuong.jpg\",\"backdropUrl\":\"/backdrops/hai-phuong.jpg\",\"trailerId\":\"SXiWz0yLLdE\",\"id\":1,\"createdAt\":\"2026-05-05T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('10#9', '10', 'Mắt Biếc', 'mat-biec', 'coming_soon', '2026-11-13', 9, '{\"title\":\"Mắt Biếc\",\"slug\":\"mat-biec\",\"tagline\":\"Mối tình đi qua cả thanh xuân.\",\"description\":\"Mối tình đơn phương của Ngạn dành cho Hà Lan – cô bạn có đôi mắt hút hồn nhưng cá tính bướng bỉnh. Từ ngộ nghĩnh trẻ con đến tình yêu thuở học trò trong sáng, rồi bao biến cố, câu chuyện trở thành một cuộc \\\"đuổi hình bắt bóng\\\" buồn da diết nhưng không nguôi hi vọng.\",\"director\":\"Victor Vũ\",\"cast\":[\"Trần Nghĩa\",\"Trúc Anh\",\"Trần Phong\",\"Khánh Vân\"],\"genres\":[\"Tình cảm\",\"Chính kịch\",\"Tâm lý\"],\"duration\":117,\"releaseDate\":\"2026-11-13\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":6.7,\"status\":\"coming_soon\",\"featured\":false,\"art\":{\"from\":\"#4ade80\",\"via\":\"#166534\",\"to\":\"#052e16\",\"accent\":\"#dcfce7\"},\"posterUrl\":\"/posters/mat-biec.jpg\",\"backdropUrl\":\"/backdrops/mat-biec.jpg\",\"trailerId\":\"ITlQ0oU7tDA\",\"id\":10,\"createdAt\":\"2026-05-14T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('11#10', '11', 'Bố Già', 'bo-gia', 'coming_soon', '2026-11-25', 10, '{\"title\":\"Bố Già\",\"slug\":\"bo-gia\",\"tagline\":\"Một người cha, cả một gia đình.\",\"description\":\"Ba Sang một mình nuôi hai con Quắn và Bù Tọt trong xóm lao động nghèo Sài Gòn. Những hiểu lầm, mâu thuẫn và tình thương bị che khuất dần lộ ra sau biến cố, buộc cả gia đình phải nhìn lại nhau.\",\"director\":\"Trấn Thành\",\"cast\":[\"Trấn Thành\",\"Tuấn Trần\",\"Ngân Chi\",\"Ngọc Giàu\",\"Lê Giang\"],\"genres\":[\"Hài\",\"Gia đình\",\"Chính kịch\"],\"duration\":128,\"releaseDate\":\"2026-11-25\",\"language\":\"Tiếng Việt\",\"age\":\"T13\",\"rating\":7.4,\"status\":\"coming_soon\",\"featured\":false,\"art\":{\"from\":\"#fbbf24\",\"via\":\"#b45309\",\"to\":\"#422006\",\"accent\":\"#fef3c7\"},\"posterUrl\":\"/posters/bo-gia.jpg\",\"backdropUrl\":\"/backdrops/bo-gia.jpg\",\"trailerId\":\"jluSu8Rw6YE\",\"id\":11,\"createdAt\":\"2026-05-15T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('12#11', '12', 'Linh Miêu: Quỷ Nhập Tràng', 'linh-mieu-quy-nhap-trang', 'coming_soon', '2026-12-06', 11, '{\"title\":\"Linh Miêu: Quỷ Nhập Tràng\",\"slug\":\"linh-mieu-quy-nhap-trang\",\"tagline\":\"Đoàn kiệu rước thây trở về cố đô.\",\"description\":\"Lấy cảm hứng từ truyền thuyết \\\"quỷ nhập tràng\\\", phim đưa người xem về xứ Huế thời chuyển giao, nơi những nghi lễ cổ và bí mật gia tộc đánh thức thứ ác linh không thể hóa giải.\",\"director\":\"Lưu Thành Luân\",\"cast\":[\"Hồng Đào\",\"Thiên An\",\"Thùy Tiên\",\"Văn Anh\",\"Samuel An\"],\"genres\":[\"Kinh dị\",\"Giật gân\",\"Bí ẩn\"],\"duration\":109,\"releaseDate\":\"2026-12-06\",\"language\":\"Tiếng Việt – Phụ đề Anh\",\"age\":\"T18\",\"rating\":0,\"status\":\"coming_soon\",\"featured\":false,\"art\":{\"from\":\"#64748b\",\"via\":\"#1e293b\",\"to\":\"#020617\",\"accent\":\"#e2e8f0\"},\"posterUrl\":\"/posters/linh-mieu.jpg\",\"backdropUrl\":\"/backdrops/linh-mieu.jpg\",\"trailerId\":\"8l4crgVt36Y\",\"id\":12,\"createdAt\":\"2026-05-16T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('13#12', '13', 'Quỷ Cẩu', 'quy-cau', 'ended', '2026-08-03', 12, '{\"title\":\"Quỷ Cẩu\",\"slug\":\"quy-cau\",\"tagline\":\"Nghiệp sát sinh không buông tha ai.\",\"description\":\"Nam về quê lo đám tang cho bố sau cái chết kinh hoàng, trong khi phải che giấu bạn gái đang mang thai. Sau khi mai táng, Nam liên tục mơ thấy gia đình bị giết và chú chó trắng Mít có biểu hiện kỳ lạ. Anh buộc phải điều tra lò mổ chó truyền thống của gia đình để giải quyết sự kiện kỳ lạ.\",\"director\":\"Lưu Thành Luân\",\"cast\":[\"Quang Tuấn\",\"Kim Xuân\",\"Vân Dung\",\"Nam Thư\",\"Hạnh Thúy\"],\"genres\":[\"Kinh dị\",\"Bí ẩn\"],\"duration\":99,\"releaseDate\":\"2026-08-03\",\"language\":\"Tiếng Việt\",\"age\":\"T18\",\"rating\":4.7,\"status\":\"ended\",\"featured\":false,\"art\":{\"from\":\"#ef4444\",\"via\":\"#7f1d1d\",\"to\":\"#000000\",\"accent\":\"#fca5a5\"},\"posterUrl\":\"/posters/quy-cau.jpg\",\"backdropUrl\":\"/backdrops/quy-cau.jpg\",\"trailerId\":\"MV4XLx_Vzw0\",\"id\":13,\"createdAt\":\"2026-05-17T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('14#13', '14', 'Song Lang', 'song-lang', 'now_showing', '2026-10-08', 13, '{\"title\":\"Song Lang\",\"slug\":\"song-lang\",\"tagline\":\"Một câu chuyện tình dưới ánh đèn cải lương.\",\"description\":\"Sài Gòn thập niên 1980. Dũng “thiên lôi” là tay anh chị chuyên đòi nợ thuê, sống lặng lẽ trong căn tập thể cũ. Một lần đi đòi nợ tại đoàn cải lương Thiên Lý, Dũng chạm mặt Linh Phụng – kép nam chính của đoàn – và sợi dây định mệnh giữa hai con người cùng nặng lòng với cải lương bắt đầu hình thành.\",\"director\":\"Leon Lê\",\"cast\":[\"Liên Bỉnh Phát\",\"Isaac\",\"Thanh Tú\",\"Hồng Thanh\",\"Mỹ Phương\"],\"genres\":[\"Chính kịch\",\"Tình cảm\",\"Âm nhạc\"],\"duration\":97,\"releaseDate\":\"2026-10-08\",\"language\":\"Tiếng Việt\",\"age\":\"T13\",\"rating\":6.8,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#f59e0b\",\"via\":\"#b45309\",\"to\":\"#1c1917\",\"accent\":\"#fef3c7\"},\"posterUrl\":\"/posters/song-lang.jpg\",\"backdropUrl\":\"/backdrops/song-lang.jpg\",\"trailerId\":\"wX8nGJFGwaU\",\"id\":14,\"createdAt\":\"2026-05-18T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('15#14', '15', 'Người Vợ Cuối Cùng', 'nguoi-vo-cuoi-cung', 'now_showing', '2026-10-13', 14, '{\"title\":\"Người Vợ Cuối Cùng\",\"slug\":\"nguoi-vo-cuoi-cung\",\"tagline\":\"Kiếp người dưới bóng phong kiến.\",\"description\":\"Lấy bối cảnh Việt Nam triều Nguyễn, phim kể về Linh – người vợ bất đắc dĩ của một viên quan tri huyện. Vì không thể sinh con nối dõi, cô chịu sự chèn ép của những người vợ lớn. Cuộc gặp lại người yêu thời thanh mai trúc mã đẩy cuộc đời cô sang trang mới.\",\"director\":\"Victor Vũ\",\"cast\":[\"Kaity Nguyễn\",\"Thuận Nguyễn\",\"Quốc Huy\",\"Lưu Đê Ly\",\"Ngọc Diệp\"],\"genres\":[\"Chính kịch\",\"Tình cảm\",\"Tâm lý\",\"Bí ẩn\"],\"duration\":133,\"releaseDate\":\"2026-10-13\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":6.8,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#a78bfa\",\"via\":\"#6d28d9\",\"to\":\"#1e1b4b\",\"accent\":\"#ddd6fe\"},\"posterUrl\":\"/posters/nguoi-vo-cuoi-cung.jpg\",\"backdropUrl\":\"/backdrops/nguoi-vo-cuoi-cung.jpg\",\"trailerId\":\"cpAESa3yUyw\",\"id\":15,\"createdAt\":\"2026-05-19T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('16#15', '16', 'Em Chưa 18', 'em-chua-18', 'now_showing', '2026-10-18', 15, '{\"title\":\"Em Chưa 18\",\"slug\":\"em-chua-18\",\"tagline\":\"Tình yêu đến khi cô ấy chưa đủ 18.\",\"description\":\"Hoàng là tay chơi bảnh tỏn, sống theo quy luật “không có đêm thứ hai” với bất kỳ cô nàng nào. Định mệnh ập đến khi anh gặp Linh Đan, có mối tình chớp nhoáng rồi phát hiện bạn gái mới chưa đủ 18 tuổi. Thế giới đào hoa của Hoàng bất ngờ thu nhỏ trong lưới tình của cô học trò tinh quái.\",\"director\":\"Lê Thanh Sơn\",\"cast\":[\"Kaity Nguyễn\",\"Kiều Minh Tuấn\",\"Will\",\"Nguyễn Tiến Dũng\",\"Kiều Trinh\"],\"genres\":[\"Hài\",\"Tình cảm\",\"Chính kịch\"],\"duration\":90,\"releaseDate\":\"2026-10-18\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":6.5,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#f472b6\",\"via\":\"#be185d\",\"to\":\"#1e1b4b\",\"accent\":\"#fbcfe8\"},\"posterUrl\":\"/posters/em-chua-18.jpg\",\"backdropUrl\":\"/backdrops/em-chua-18.jpg\",\"trailerId\":\"_affkHceSj4\",\"id\":16,\"createdAt\":\"2026-05-20T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('17#16', '17', 'Tro Tàn Rực Rỡ', 'tro-tan-ruc-ro', 'now_showing', '2026-10-21', 16, '{\"title\":\"Tro Tàn Rực Rỡ\",\"slug\":\"tro-tan-ruc-ro\",\"tagline\":\"Ba người phụ nữ, ba cách giữ lửa yêu.\",\"description\":\"Lấy bối cảnh làng chài Thơm Rơm ven biển Cà Mau, phim xoay quanh ba người phụ nữ có cuộc sống tình yêu khác thường. Câu chuyện về cách họ yêu, cách giữ người đàn ông của mình và những mảnh đời còn lại sau giông bão.\",\"director\":\"Bùi Thạc Chuyên\",\"cast\":[\"Lê Công Hoàng\",\"Juliet Bảo Ngọc Doling\",\"Phương Anh Đào\",\"Quang Tuấn\",\"Hạnh Thúy\"],\"genres\":[\"Chính kịch\",\"Tâm lý\",\"Tình cảm\"],\"duration\":117,\"releaseDate\":\"2026-10-21\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":7,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#34d399\",\"via\":\"#065f46\",\"to\":\"#052e16\",\"accent\":\"#a7f3d0\"},\"posterUrl\":\"/posters/tro-tan-ruc-ro.jpg\",\"backdropUrl\":\"/backdrops/tro-tan-ruc-ro.jpg\",\"trailerId\":\"Sx0gdaeeGi4\",\"id\":17,\"createdAt\":\"2026-05-21T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('18#17', '18', 'Sút', 'sut', 'now_showing', '2026-10-23', 17, '{\"title\":\"Sút\",\"slug\":\"sut\",\"tagline\":\"Bóng đá, đam mê và gia đình.\",\"description\":\"Bộ phim điện ảnh Việt Nam đầu tiên lấy đề tài bóng đá, khơi dậy tinh thần hết mình với ước mơ tuổi trẻ. Không chỉ nói về bóng đá, phim còn là câu chuyện về đam mê, tình cảm gia đình và những người trẻ chắp nối ước mơ của nhau.\",\"director\":\"Việt Max\",\"cast\":[\"Hà Hiền\",\"Gin Tuấn Kiệt\",\"Huyme\",\"Nhung Kate\",\"Tùng Mint\"],\"genres\":[\"Thể thao\",\"Hài\",\"Gia đình\",\"Chính kịch\"],\"duration\":97,\"releaseDate\":\"2026-10-23\",\"language\":\"Tiếng Việt\",\"age\":\"P\",\"rating\":0,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#84cc16\",\"via\":\"#3f6212\",\"to\":\"#0c1a05\",\"accent\":\"#d9f99d\"},\"posterUrl\":\"/posters/sut.jpg\",\"backdropUrl\":\"/backdrops/sut.jpg\",\"trailerId\":\"dqmXjR0tZfI\",\"id\":18,\"createdAt\":\"2026-05-22T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('19#18', '19', 'Em và Trịnh', 'em-va-trinh', 'now_showing', '2026-10-10', 18, '{\"title\":\"Em và Trịnh\",\"slug\":\"em-va-trinh\",\"tagline\":\"Một đời nhạc, một đời tình.\",\"description\":\"Tác phẩm xoay quanh cuộc đời Trịnh Công Sơn từ thời trẻ đến lúc trung niên trong khoảng những năm 1960-1990, điểm nhấn là câu chuyện giữa cố nhạc sĩ và cô gái Dao Ánh.\",\"director\":\"Phan Gia Nhật Linh\",\"cast\":[\"Avin Lu\",\"Lan Thy\",\"Hoàng Hà\",\"Trần Lực\",\"Bùi Lan Hương\"],\"genres\":[\"Âm nhạc\",\"Tình cảm\",\"Chính kịch\"],\"duration\":136,\"releaseDate\":\"2026-10-10\",\"language\":\"Tiếng Việt\",\"age\":\"T13\",\"rating\":0,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#f59e0b\",\"via\":\"#b45309\",\"to\":\"#1c1917\",\"accent\":\"#fef3c7\"},\"posterUrl\":\"/posters/em-va-trinh.jpg\",\"backdropUrl\":\"/backdrops/em-va-trinh.jpg\",\"trailerId\":\"IosqnBOkk2I\",\"id\":19,\"createdAt\":\"2026-05-23T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('2#1', '2', 'Đào, Phở và Piano', 'dao-pho-va-piano', 'now_showing', '2026-10-02', 1, '{\"title\":\"Đào, Phở và Piano\",\"slug\":\"dao-pho-va-piano\",\"tagline\":\"Hà Nội 60 ngày đêm, tình yêu giữa bom đạn.\",\"description\":\"Lấy bối cảnh 60 ngày đêm cuối năm 1946 đầu năm 1947 ở Hà Nội, phim theo chân chàng dân quân Văn Dân và nàng tiểu thư đam mê dương cầm Thục Hương. Giữa bom đạn, họ quyết định cố thủ lại thủ đô đã tan hoang thay vì di tản lên chiến khu.\",\"director\":\"Phi Tiến Sơn\",\"cast\":[\"Cao Thị Thuỳ Linh\",\"Doãn Quốc Đam\",\"Trần Lực\",\"Trung Hiếu\",\"Tuấn Hưng\"],\"genres\":[\"Lịch sử\",\"Chiến tranh\",\"Tình cảm\",\"Chính kịch\"],\"duration\":100,\"releaseDate\":\"2026-10-02\",\"language\":\"Tiếng Việt – Phụ đề Anh\",\"age\":\"T13\",\"rating\":6.3,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#f59e0b\",\"via\":\"#78350f\",\"to\":\"#1c1917\",\"accent\":\"#fde68a\"},\"posterUrl\":\"/posters/dao-pho-va-piano.jpg\",\"backdropUrl\":\"/backdrops/dao-pho-va-piano.jpg\",\"trailerId\":\"qn1t_biQigc\",\"id\":2,\"createdAt\":\"2026-05-06T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('20#19', '20', 'Mùi Cỏ Cháy', 'mui-co-chay', 'now_showing', '2026-10-04', 19, '{\"title\":\"Mùi Cỏ Cháy\",\"slug\":\"mui-co-chay\",\"tagline\":\"Mùa hè đỏ lửa, tuổi trẻ và nỗi nhớ.\",\"description\":\"\\\"Mùi cỏ cháy\\\" lấy bối cảnh Mùa hè đỏ lửa 1972 với trận chiến tại Thành cổ Quảng Trị. Bốn sinh viên Hà Nội lên đường nhập ngũ năm 1971, được huấn luyện tốc hành và tham gia chiến đấu tại Thành cổ. Câu chuyện được kể lại từ ký ức của Hoàng khi ông trở về chiến trường xưa.\",\"director\":\"Nguyễn Hữu Mười\",\"cast\":[\"Nguyễn Năng Tùng\",\"Hữu Mười\",\"Lê Văn Thơm\",\"Tô Dũng\",\"Thanh Sơn\"],\"genres\":[\"Chiến tranh\",\"Lịch sử\",\"Chính kịch\"],\"duration\":97,\"releaseDate\":\"2026-10-04\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":7.8,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#84cc16\",\"via\":\"#3f6212\",\"to\":\"#1a2e05\",\"accent\":\"#d9f99d\"},\"posterUrl\":\"/posters/mui-co-chay.jpg\",\"backdropUrl\":\"/backdrops/mui-co-chay.jpg\",\"trailerId\":\"Up9T0jRpBOA\",\"id\":20,\"createdAt\":\"2026-05-24T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('21#20', '21', 'Truy Sát', 'truy-sat', 'now_showing', '2026-10-06', 20, '{\"title\":\"Truy Sát\",\"slug\":\"truy-sat\",\"tagline\":\"Không có đường lùi cho người đi tìm công lý.\",\"description\":\"Một băng đảng ma túy quốc tế nhắm tới Việt Nam, và nữ cảnh sát cứng rắn nhất phải đưa chúng ra trước công lý. Cuộc truy đuổi xuyên biên giới đẩy cô vào những trận chiến nghẹt thở giữa tội phạm và lòng trung thành.\",\"director\":\"Cường Ngô\",\"cast\":[\"Trương Ngọc Ánh\",\"Marcus Guilhem\",\"Mike Leeder\",\"Trung Ly\",\"Thiên Nguyễn\"],\"genres\":[\"Hành động\",\"Võ thuật\",\"Giật gân\"],\"duration\":90,\"releaseDate\":\"2026-10-06\",\"language\":\"Tiếng Việt – Phụ đề Anh\",\"age\":\"T18\",\"rating\":7.8,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#f97316\",\"via\":\"#9a3412\",\"to\":\"#0c0a09\",\"accent\":\"#fed7aa\"},\"posterUrl\":\"/posters/truy-sat.jpg\",\"backdropUrl\":\"/backdrops/truy-sat.jpg\",\"trailerId\":\"sAibeuzwd_o\",\"id\":21,\"createdAt\":\"2026-05-25T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('22#21', '22', 'Người Bất Tử', 'nguoi-bat-tu', 'now_showing', '2026-10-09', 21, '{\"title\":\"Người Bất Tử\",\"slug\":\"nguoi-bat-tu\",\"tagline\":\"Ba thế kỷ, một lời nguyền.\",\"description\":\"Những giấc mơ và ảo ảnh dẫn An đến một hang động bí ẩn, nơi cô phát hiện bí mật kinh hoàng về Hùng – người đàn ông đã sống qua ba thế kỷ. Cuộc đời đầy biến động của Hùng dần hé lộ.\",\"director\":\"Victor Vũ\",\"cast\":[\"Quách Ngọc Ngoan\",\"Ngọc Diệp\",\"Jun Vũ\",\"Thanh Tú\",\"Lâm Vissay\"],\"genres\":[\"Kinh dị\",\"Giật gân\",\"Giả tượng\",\"Bí ẩn\"],\"duration\":132,\"releaseDate\":\"2026-10-09\",\"language\":\"Tiếng Việt\",\"age\":\"T18\",\"rating\":6.3,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#dc2626\",\"via\":\"#7f1d1d\",\"to\":\"#0c0a09\",\"accent\":\"#fecaca\"},\"posterUrl\":\"/posters/nguoi-bat-tu.jpg\",\"backdropUrl\":\"/backdrops/nguoi-bat-tu.jpg\",\"trailerId\":\"6VEVPtFDN_U\",\"id\":22,\"createdAt\":\"2026-05-26T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('23#22', '23', 'Quả Tim Máu', 'qua-tim-mau', 'now_showing', '2026-10-15', 22, '{\"title\":\"Quả Tim Máu\",\"slug\":\"qua-tim-mau\",\"tagline\":\"Trái tim không biết nói dối.\",\"description\":\"Linh, người nhận ghép tim, bắt đầu có những cơn ác mộng và tầm nhìn dẫn đến một ngôi nhà ở vùng nông thôn xa xôi. Cô tin rằng chủ nhân trước của trái tim đang cố gửi một thông điệp từ bên kia thế giới.\",\"director\":\"Victor Vũ\",\"cast\":[\"Thái Hòa\",\"Quý Bình\",\"Tú Vi\",\"Nhã Phương\",\"Kim Xuân\"],\"genres\":[\"Kinh dị\",\"Giật gân\",\"Bí ẩn\",\"Hài\"],\"duration\":97,\"releaseDate\":\"2026-10-15\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":8.4,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#ef4444\",\"via\":\"#991b1b\",\"to\":\"#1c1917\",\"accent\":\"#fca5a5\"},\"posterUrl\":\"/posters/qua-tim-mau.jpg\",\"backdropUrl\":\"/backdrops/qua-tim-mau.jpg\",\"trailerId\":\"eFUOOcTZI_4\",\"id\":23,\"createdAt\":\"2026-05-27T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('24#23', '24', 'Chị Mười Ba 2: 3 Ngày Sinh Tử', 'chi-muoi-ba', 'now_showing', '2026-10-17', 23, '{\"title\":\"Chị Mười Ba 2: 3 Ngày Sinh Tử\",\"slug\":\"chi-muoi-ba\",\"tagline\":\"Ba ngày để sống, một đời để trả.\",\"description\":\"Sau khi lật đổ ông trùm Hắc Hổ và đập tan âm mưu của Anh Hai, Chị Mười Ba cùng An Cư Nghĩa Đoàn tưởng đã có thể yên ổn làm ăn. Nhưng một loạt biến cố mới buộc chị phải tái xuất trong ba ngày sinh tử.\",\"director\":\"Võ Thanh Hòa\",\"cast\":[\"Thu Trang\",\"Tiến Luật\",\"Kiều Minh Tuấn\",\"Trương Minh Quốc Thái\"],\"genres\":[\"Hài\",\"Hành động\",\"Võ thuật\"],\"duration\":90,\"releaseDate\":\"2026-10-17\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":4,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#facc15\",\"via\":\"#a16207\",\"to\":\"#1c1917\",\"accent\":\"#fef08a\"},\"posterUrl\":\"/posters/chi-muoi-ba.jpg\",\"backdropUrl\":\"/backdrops/chi-muoi-ba.jpg\",\"trailerId\":\"Ncwkodt5dA4\",\"id\":24,\"createdAt\":\"2026-05-28T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('25#24', '25', 'Dế Mèn: Cuộc Phiêu Lưu Tới Xóm Lầy Lội', 'de-men', 'now_showing', '2026-10-25', 24, '{\"title\":\"Dế Mèn: Cuộc Phiêu Lưu Tới Xóm Lầy Lội\",\"slug\":\"de-men\",\"tagline\":\"Phiêu lưu tới xóm lầy lội.\",\"description\":\"Lấy cảm hứng từ tác phẩm \\\"Dế Mèn phiêu lưu ký\\\" của Tô Hoài, phim theo chân Dế Mèn và những người bạn qua Hà Nội hiện đại để cứu Xóm Lầy Lội – vùng đất từng xanh tươi nay bị đe dọa.\",\"director\":\"Mai Phương\",\"cast\":[\"Lê Bống\",\"Ali Thục Phương\",\"Nguyễn Anh Tuấn\",\"Võ Huyền Chi\",\"Hồ Tiến Đạt\"],\"genres\":[\"Hoạt hình\",\"Phiêu lưu\",\"Gia đình\",\"Âm nhạc\"],\"duration\":84,\"releaseDate\":\"2026-10-25\",\"language\":\"Tiếng Việt\",\"age\":\"P\",\"rating\":5,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#4ade80\",\"via\":\"#15803d\",\"to\":\"#052e16\",\"accent\":\"#bbf7d0\"},\"posterUrl\":\"/posters/de-men.jpg\",\"backdropUrl\":\"/backdrops/de-men.jpg\",\"trailerId\":\"Vwwsh0QxwIs\",\"id\":25,\"createdAt\":\"2026-05-29T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('26#25', '26', 'Trạng Quỳnh Nhí: Truyền Thuyết Kim Ngưu', 'trang-quynh-nhi', 'now_showing', '2026-10-26', 25, '{\"title\":\"Trạng Quỳnh Nhí: Truyền Thuyết Kim Ngưu\",\"slug\":\"trang-quynh-nhi\",\"tagline\":\"Truyền thuyết Kim Ngưu thức giấc.\",\"description\":\"Cuộc phiêu lưu của Quỳnh và nhóm bạn cùng một chú trâu nước bí ẩn, đưa cả nhóm vào hành trình khám phá truyền thuyết Kim Ngưu và những thử thách kỳ ảo.\",\"director\":\"Trịnh Lâm Tùng\",\"cast\":[\"Trọng Phan\",\"Lê Hiếu\",\"Tạ Tuấn Minh\",\"Đới Anh Quân\",\"Nông Dũng Nam\"],\"genres\":[\"Hoạt hình\",\"Phiêu lưu\",\"Giả tượng\",\"Gia đình\"],\"duration\":98,\"releaseDate\":\"2026-10-26\",\"language\":\"Tiếng Việt\",\"age\":\"P\",\"rating\":0,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#22d3ee\",\"via\":\"#0e7490\",\"to\":\"#020617\",\"accent\":\"#a5f3fc\"},\"posterUrl\":\"/posters/trang-quynh-nhi.jpg\",\"backdropUrl\":\"/backdrops/trang-quynh-nhi.jpg\",\"trailerId\":\"YQdA6Ou4xZk\",\"id\":26,\"createdAt\":\"2026-05-30T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('27#26', '27', 'Tôi Thấy Hoa Vàng Trên Cỏ Xanh', 'toi-thay-hoa-vang', 'now_showing', '2026-10-19', 26, '{\"title\":\"Tôi Thấy Hoa Vàng Trên Cỏ Xanh\",\"slug\":\"toi-thay-hoa-vang\",\"tagline\":\"Tuổi thơ, tình bạn và những điều chưa kịp nói.\",\"description\":\"Lấy bối cảnh tại vùng quê Việt Nam, bộ phim kể về câu chuyện tình cảm ngây thơ trong sáng, tình bạn đẹp và tình làng xóm của hai anh em Thiều, Tường và cô bé Mận.\",\"director\":\"Victor Vũ\",\"cast\":[\"Thịnh Vinh\",\"Trọng Khang\",\"Lâm Thanh Mỹ\",\"My Anh\",\"Mai Thế Hiệp\"],\"genres\":[\"Tình cảm\",\"Gia đình\",\"Chính kịch\",\"Tâm lý\"],\"duration\":103,\"releaseDate\":\"2026-10-19\",\"language\":\"Tiếng Việt\",\"age\":\"P\",\"rating\":6.9,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#84cc16\",\"via\":\"#3f6212\",\"to\":\"#1a2e05\",\"accent\":\"#d9f99d\"},\"posterUrl\":\"/posters/toi-thay-hoa-vang.jpg\",\"backdropUrl\":\"/backdrops/toi-thay-hoa-vang.jpg\",\"trailerId\":\"wmjiCP6R-7I\",\"id\":27,\"createdAt\":\"2026-05-31T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('28#27', '28', 'Đất Rừng Phương Nam', 'dat-rung-phuong-nam', 'now_showing', '2026-10-05', 27, '{\"title\":\"Đất Rừng Phương Nam\",\"slug\":\"dat-rung-phuong-nam\",\"tagline\":\"Về phương Nam, nơi đất rừng gọi tên.\",\"description\":\"Đất Rừng Phương Nam phiên bản điện ảnh được kế thừa và phát triển từ tiểu thuyết cùng tên của nhà văn Đoàn Giỏi. Phim kể về hành trình phiêu lưu của An – cậu bé chẳng may mất mẹ trên đường đi tìm cha. Cùng An, khán giả trải nghiệm sự trù phú của thiên nhiên và nét đẹp văn hoá đặc sắc của vùng đất Nam Kì Lục Tỉnh.\",\"director\":\"Nguyễn Quang Dũng\",\"cast\":[\"Hạo Khang\",\"Trấn Thành\",\"Công Ninh\",\"Mai Tài Phến\",\"Tuấn Trần\"],\"genres\":[\"Phiêu lưu\",\"Gia đình\",\"Chính kịch\",\"Chiến tranh\"],\"duration\":100,\"releaseDate\":\"2026-10-05\",\"language\":\"Tiếng Việt\",\"age\":\"P\",\"rating\":5.3,\"status\":\"now_showing\",\"featured\":true,\"art\":{\"from\":\"#10b981\",\"via\":\"#065f46\",\"to\":\"#052e16\",\"accent\":\"#a7f3d0\"},\"posterUrl\":\"/posters/dat-rung-phuong-nam.jpg\",\"backdropUrl\":\"/backdrops/dat-rung-phuong-nam.jpg\",\"trailerId\":\"hktzirCnJmQ\",\"id\":28,\"createdAt\":\"2026-06-01T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('29#28', '29', 'Tấm Cám: Chuyện Chưa Kể', 'tam-cam', 'now_showing', '2026-10-03', 28, '{\"title\":\"Tấm Cám: Chuyện Chưa Kể\",\"slug\":\"tam-cam\",\"tagline\":\"Cổ tích chưa từng kể như thế này.\",\"description\":\"Tấm Cám Chuyện Chưa Kể lấy cảm hứng từ câu chuyện cổ tích quen thuộc nhưng khai thác dưới góc độ kỳ ảo. Vẫn là nàng Tấm hiền lành bị mẹ con Cám hãm hại, nhưng câu chuyện bùng nổ hơn với vai trò của Thái tử và những bí ẩn trong vương triều.\",\"director\":\"Ngô Thanh Vân\",\"cast\":[\"Ngô Thanh Vân\",\"Hạ Vi\",\"Ninh Dương Lan Ngọc\",\"Isaac\",\"Thành Lộc\"],\"genres\":[\"Giả tượng\",\"Kinh dị\",\"Chính kịch\",\"Bí ẩn\"],\"duration\":115,\"releaseDate\":\"2026-10-03\",\"language\":\"Tiếng Việt\",\"age\":\"T13\",\"rating\":4.8,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#facc15\",\"via\":\"#92400e\",\"to\":\"#1c0a0a\",\"accent\":\"#fde68a\"},\"posterUrl\":\"/posters/tam-cam.jpg\",\"backdropUrl\":\"/backdrops/tam-cam.jpg\",\"trailerId\":\"6oqXSG5FKd4\",\"id\":29,\"createdAt\":\"2026-06-02T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('3#2', '3', 'Mai', 'mai', 'now_showing', '2026-10-14', 2, '{\"title\":\"Mai\",\"slug\":\"mai\",\"tagline\":\"Có những người sinh ra để yêu thương, không phải để giữ lại.\",\"description\":\"Mai là người phụ nữ từng trải, mang trong mình nhiều vết thương. Cuộc gặp gỡ với Dương – chàng trai trẻ giàu cảm xúc – mở ra một chương mới nhưng cũng đặt cả hai trước những lựa chọn nghiệt ngã.\",\"director\":\"Trấn Thành\",\"cast\":[\"Phương Anh Đào\",\"Tuấn Trần\",\"Hồng Đào\",\"NSND Ngọc Giàu\"],\"genres\":[\"Tâm lý\",\"Tình cảm\",\"Gia đình\"],\"duration\":131,\"releaseDate\":\"2026-10-14\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":7.9,\"status\":\"now_showing\",\"featured\":true,\"art\":{\"from\":\"#f472b6\",\"via\":\"#9d174d\",\"to\":\"#1e1b4b\",\"accent\":\"#fbcfe8\"},\"posterUrl\":\"/posters/mai.jpg\",\"backdropUrl\":\"/backdrops/mai.jpg\",\"trailerId\":\"HXWRTGbhb4U\",\"id\":3,\"createdAt\":\"2026-05-07T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('30#29', '30', 'Thiên Mệnh Anh Hùng', 'thien-menh-anh-hung', 'now_showing', '2026-10-02', 29, '{\"title\":\"Thiên Mệnh Anh Hùng\",\"slug\":\"thien-menh-anh-hung\",\"tagline\":\"Một lời sấm, một mối thù, một anh hùng.\",\"description\":\"Sau vụ thảm án Lệ Chi viên, gia tộc Nguyễn Trãi chỉ còn một đứa bé 5 tuổi sống sót, được gia tướng đem đi trốn để tránh sự truy sát của phe Tuyên Từ Hoàng thái hậu. Mười sáu năm sau, người xưa trở về giữa vòng xoáy quyền lực và mối thù gia tộc.\",\"director\":\"Victor Vũ\",\"cast\":[\"Huỳnh Đông\",\"Midu\",\"Khương Ngọc\",\"Minh Thuận\",\"Vân Trang\"],\"genres\":[\"Hành động\",\"Võ thuật\",\"Lịch sử\",\"Chính kịch\"],\"duration\":90,\"releaseDate\":\"2026-10-02\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":6.3,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#dc2626\",\"via\":\"#7f1d1d\",\"to\":\"#1c1917\",\"accent\":\"#fecaca\"},\"posterUrl\":\"/posters/thien-menh-anh-hung.jpg\",\"backdropUrl\":\"/backdrops/thien-menh-anh-hung.jpg\",\"trailerId\":\"kiTeyH3xASE\",\"id\":30,\"createdAt\":\"2026-06-03T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('31#30', '31', 'Bụi Đời Chợ Lớn', 'bui-doi-cho-lon', 'now_showing', '2026-10-07', 30, '{\"title\":\"Bụi Đời Chợ Lớn\",\"slug\":\"bui-doi-cho-lon\",\"tagline\":\"Chợ Lớn không có chỗ cho người yếu.\",\"description\":\"Trong thế giới ngầm tại Sài Gòn, Chợ Lớn là trái tim của cả thành phố – ai có Chợ Lớn thì có Sài Gòn. Máu và nước mắt đổ xuống cho những cuộc tranh quyền đoạt vị khốc liệt, xoay quanh mối quan hệ phức tạp giữa bốn nhân vật.\",\"director\":\"Charlie Nguyễn\",\"cast\":[\"Hoàng Phúc\",\"Long Điền\",\"Hà Hiền\",\"Huỳnh Bích Phương\",\"Hoàng Phi\"],\"genres\":[\"Hành động\",\"Tội phạm\",\"Chính kịch\"],\"duration\":85,\"releaseDate\":\"2026-10-07\",\"language\":\"Tiếng Việt\",\"age\":\"T18\",\"rating\":5.3,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#ef4444\",\"via\":\"#7f1d1d\",\"to\":\"#0c0a09\",\"accent\":\"#fca5a5\"},\"posterUrl\":\"/posters/bui-doi-cho-lon.jpg\",\"backdropUrl\":\"/backdrops/bui-doi-cho-lon.jpg\",\"trailerId\":\"b9pw1sdwyYs\",\"id\":31,\"createdAt\":\"2026-06-04T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('32#31', '32', 'Vệ Sĩ Sài Gòn', 've-si-sai-gon', 'now_showing', '2026-10-11', 31, '{\"title\":\"Vệ Sĩ Sài Gòn\",\"slug\":\"ve-si-sai-gon\",\"tagline\":\"Bảo vệ người khác, bảo vệ chính mình.\",\"description\":\"Bộ phim chiếu rạp đầu tiên của Việt Nam nói về nghề vệ sĩ. Mr. Hoàn Hảo của Kim Lý cùng Mr. Mê Gái của Thái Hòa phải thực hiện một nhiệm vụ tưởng dễ nhưng hóa ra cực khó, kéo theo chuỗi tình huống dở khóc dở cười.\",\"director\":\"Ken Ochiai\",\"cast\":[\"Thái Hòa\",\"Chi Pu\",\"B Trần\",\"Kim Ly\",\"Khương Ngọc\"],\"genres\":[\"Hành động\",\"Hài\"],\"duration\":112,\"releaseDate\":\"2026-10-11\",\"language\":\"Tiếng Việt\",\"age\":\"T13\",\"rating\":6,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#38bdf8\",\"via\":\"#1d4ed8\",\"to\":\"#0c1a2e\",\"accent\":\"#bae6fd\"},\"posterUrl\":\"/posters/ve-si-sai-gon.jpg\",\"backdropUrl\":\"/backdrops/ve-si-sai-gon.jpg\",\"trailerId\":\"faZhrk93yW0\",\"id\":32,\"createdAt\":\"2026-06-05T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('33#32', '33', 'Gái Già Lắm Chiêu V', 'gai-gia-lam-chieu-v', 'now_showing', '2026-10-12', 32, '{\"title\":\"Gái Già Lắm Chiêu V\",\"slug\":\"gai-gia-lam-chieu-v\",\"tagline\":\"Tình thân hay tiền tài?\",\"description\":\"Cuộc chiến “chị – em máu mủ tình thâm” chỉ vì hai chữ TÌNH – TIỀN của ba chị em gái Lý gia tại biệt thự Bạch Trà Viên xứ Huế. Từ chị em ruột thịt, họ trở thành những kẻ đối đầu trong vòng xoáy được – mất.\",\"director\":\"Bảo Nhân\",\"cast\":[\"Hồng Vân\",\"Kaity Nguyễn\",\"Khương Lê\",\"Hoàng Dũng\",\"Lê Khánh\"],\"genres\":[\"Hài\",\"Chính kịch\",\"Tâm lý\"],\"duration\":115,\"releaseDate\":\"2026-10-12\",\"language\":\"Tiếng Việt\",\"age\":\"T13\",\"rating\":4.5,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#f472b6\",\"via\":\"#9d174d\",\"to\":\"#1e1b4b\",\"accent\":\"#fbcfe8\"},\"posterUrl\":\"/posters/gai-gia-lam-chieu-v.jpg\",\"backdropUrl\":\"/backdrops/gai-gia-lam-chieu-v.jpg\",\"trailerId\":\"IxfeXhGAa9M\",\"id\":33,\"createdAt\":\"2026-06-06T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('34#33', '34', 'Cua Lại Vợ Bầu', 'cua-lai-vo-bau', 'now_showing', '2026-10-13', 33, '{\"title\":\"Cua Lại Vợ Bầu\",\"slug\":\"cua-lai-vo-bau\",\"tagline\":\"Yêu nhau bảy năm, cua lại một lần.\",\"description\":\"Trọng Thoại và Nhã Linh yêu nhau đã bảy năm. Những lỗi lầm nho nhỏ tích tụ thành mâu thuẫn lớn, lại thêm người cũ Quý Khánh xuất hiện khiến Nhã Linh xao lòng. Rồi cô có thai – và câu hỏi đứa bé là của ai kéo cả hai vào rắc rối.\",\"director\":\"Nhất Trung\",\"cast\":[\"Trấn Thành\",\"Ninh Dương Lan Ngọc\",\"Anh Tú Atus\",\"Mạc Văn Khoa\",\"Khả Như\"],\"genres\":[\"Hài\",\"Gia đình\",\"Tình cảm\"],\"duration\":90,\"releaseDate\":\"2026-10-13\",\"language\":\"Tiếng Việt\",\"age\":\"T13\",\"rating\":7.3,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#fbbf24\",\"via\":\"#b45309\",\"to\":\"#422006\",\"accent\":\"#fef3c7\"},\"posterUrl\":\"/posters/cua-lai-vo-bau.jpg\",\"backdropUrl\":\"/backdrops/cua-lai-vo-bau.jpg\",\"trailerId\":\"l8vTMxuvz6Y\",\"id\":34,\"createdAt\":\"2026-06-07T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('35#34', '35', 'Chị Chị Em Em', 'chi-chi-em-em', 'now_showing', '2026-10-14', 34, '{\"title\":\"Chị Chị Em Em\",\"slug\":\"chi-chi-em-em\",\"tagline\":\"Yêu – hận – tình – thù giữa hai người phụ nữ.\",\"description\":\"Sự kết hợp chưa từng có giữa Thanh Hằng và Chi Pu cùng câu chuyện ly kỳ về yêu – hận – tình – thù đằng sau hai người phụ nữ xinh đẹp, đưa cả hai vào vòng xoáy của ghen tuông và toan tính.\",\"director\":\"Kathy Uyen\",\"cast\":[\"Thanh Hằng\",\"Chi Pu\",\"Lãnh Thanh\",\"Kathy Uyen\"],\"genres\":[\"Chính kịch\",\"Tâm lý\",\"Tình cảm\",\"Giật gân\"],\"duration\":94,\"releaseDate\":\"2026-10-14\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":5.5,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#fb7185\",\"via\":\"#9f1239\",\"to\":\"#1f0a12\",\"accent\":\"#fecdd3\"},\"posterUrl\":\"/posters/chi-chi-em-em.jpg\",\"backdropUrl\":\"/backdrops/chi-chi-em-em.jpg\",\"trailerId\":\"Z73wnPtHdEg\",\"id\":35,\"createdAt\":\"2026-06-08T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('36#35', '36', 'Cô Ba Sài Gòn', 'co-ba-sai-gon', 'now_showing', '2026-10-16', 35, '{\"title\":\"Cô Ba Sài Gòn\",\"slug\":\"co-ba-sai-gon\",\"tagline\":\"Chiếc áo dài giữ hồn Sài Gòn.\",\"description\":\"Năm 1969, nhà may Thanh Nữ là nhà may áo dài nổi tiếng nhất Sài Gòn. Bà chủ Thanh Mai có hai cô con gái: Như Ý và cô con nuôi Thanh Loan. Như Ý thích thiết kế đồ Tây và cho rằng áo dài đã quá xưa, cho đến khi những biến cố gia đình buộc cô nhìn lại.\",\"director\":\"Kay Nguyễn\",\"cast\":[\"Ninh Dương Lan Ngọc\",\"Hồng Vân\",\"Ngô Thanh Vân\",\"Diễm My 9x\",\"S.T Sơn Thạch\"],\"genres\":[\"Chính kịch\",\"Hài\",\"Tâm lý\"],\"duration\":100,\"releaseDate\":\"2026-10-16\",\"language\":\"Tiếng Việt\",\"age\":\"T13\",\"rating\":6.1,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#f59e0b\",\"via\":\"#0f766e\",\"to\":\"#042f2e\",\"accent\":\"#fef3c7\"},\"posterUrl\":\"/posters/co-ba-sai-gon.jpg\",\"backdropUrl\":\"/backdrops/co-ba-sai-gon.jpg\",\"trailerId\":\"YP4TDQVkZO4\",\"id\":36,\"createdAt\":\"2026-06-09T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('37#36', '37', 'Yêu', 'yeu', 'now_showing', '2026-10-18', 36, '{\"title\":\"Yêu\",\"slug\":\"yeu\",\"tagline\":\"Yêu là dám chọn.\",\"description\":\"Bộ phim xoay quanh mối quan hệ tình bạn, tình yêu của Nhi, Hoàng, Tú và Miến. Nhi – cô gái xinh xắn với khát vọng ca hát – đứng giữa tình cảm dành cho bạn trai cứng nhắc và rung động mới, buộc cô phải lựa chọn điều mình thật sự muốn.\",\"director\":\"Việt Max\",\"cast\":[\"Chi Pu\",\"Gil Le\",\"B Trần\",\"Phở Đặc Biệt\",\"Lâm Thanh Mỹ\"],\"genres\":[\"Tình cảm\",\"Chính kịch\"],\"duration\":106,\"releaseDate\":\"2026-10-18\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":5.1,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#38bdf8\",\"via\":\"#7c3aed\",\"to\":\"#172554\",\"accent\":\"#e9d5ff\"},\"posterUrl\":\"/posters/yeu.jpg\",\"backdropUrl\":\"/backdrops/yeu.jpg\",\"trailerId\":\"bh-WIE0Lo9w\",\"id\":37,\"createdAt\":\"2026-06-10T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('38#37', '38', 'Ma Da', 'ma-da', 'now_showing', '2026-10-27', 37, '{\"title\":\"Ma Da\",\"slug\":\"ma-da\",\"tagline\":\"Sông sâu không giấu được oan hồn.\",\"description\":\"Phim kể về bà Lệ, người làm nghề vớt xác người chết trên sông để đưa về với gia đình. Trong quá trình làm nghề, bà đắc tội với Ma Da – oan hồn dưới sông chuyên kéo chân người thế mạng. Oán hận của cả hai khiến Ma Da bắt mất bé Nhung, con gái bà Lệ.\",\"director\":\"Nguyễn Hữu Hoàng\",\"cast\":[\"Việt Hương\",\"Thành Lộc\",\"Trung Dân\",\"Cẩm Ly\",\"Hoàng Mèo\"],\"genres\":[\"Kinh dị\",\"Bí ẩn\",\"Giật gân\"],\"duration\":95,\"releaseDate\":\"2026-10-27\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":6.5,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#22d3ee\",\"via\":\"#0e7490\",\"to\":\"#020617\",\"accent\":\"#a5f3fc\"},\"posterUrl\":\"/posters/ma-da.jpg\",\"backdropUrl\":\"/backdrops/ma-da.jpg\",\"trailerId\":\"ocWpaBmLy3I\",\"id\":38,\"createdAt\":\"2026-06-11T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('39#38', '39', 'Kẻ Ăn Hồn', 'ke-an-hon', 'now_showing', '2026-10-28', 38, '{\"title\":\"Kẻ Ăn Hồn\",\"slug\":\"ke-an-hon\",\"tagline\":\"Năm mạng đổi một bình rượu.\",\"description\":\"Phim về hàng loạt cái chết bí ẩn ở Làng Địa Ngục, nơi có ma thuật cổ xưa: năm mạng đổi bình Rượu Sọ Người. Thập Nương – cô gái áo đỏ – là kẻ nắm giữ bí thuật luyện nên loại rượu mạnh nhất.\",\"director\":\"Trần Hữu Tấn\",\"cast\":[\"Hoàng Hà\",\"Võ Điền Gia Huy\",\"Thanh Trực\",\"Lan Phương\",\"Chiều Xuân\"],\"genres\":[\"Kinh dị\",\"Bí ẩn\",\"Giật gân\"],\"duration\":109,\"releaseDate\":\"2026-10-28\",\"language\":\"Tiếng Việt\",\"age\":\"T18\",\"rating\":6,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#dc2626\",\"via\":\"#450a0a\",\"to\":\"#000000\",\"accent\":\"#fca5a5\"},\"posterUrl\":\"/posters/ke-an-hon.jpg\",\"backdropUrl\":\"/backdrops/ke-an-hon.jpg\",\"trailerId\":\"PqGn9wWjoUk\",\"id\":39,\"createdAt\":\"2026-06-12T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('4#3', '4', 'Lật Mặt 7: Một Điều Ước', 'lat-mat-7-mot-dieu-uoc', 'now_showing', '2026-10-07', 3, '{\"title\":\"Lật Mặt 7: Một Điều Ước\",\"slug\":\"lat-mat-7-mot-dieu-uoc\",\"tagline\":\"Một điều ước, cả gia đình thay đổi.\",\"description\":\"Câu chuyện về bà Hai và năm người con với những toan tính, hiểu lầm và tình thương bị che khuất. Một biến cố khiến cả gia đình phải ngồi lại và nhìn nhau thật lòng.\",\"director\":\"Lý Hải\",\"cast\":[\"Lý Hải\",\"Minh Hà\",\"Trường Thịnh\",\"Quách Ngọc Tuyên\"],\"genres\":[\"Gia đình\",\"Tâm lý\",\"Hài\"],\"duration\":138,\"releaseDate\":\"2026-10-07\",\"language\":\"Tiếng Việt\",\"age\":\"T13\",\"rating\":7.5,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#fbbf24\",\"via\":\"#b45309\",\"to\":\"#422006\",\"accent\":\"#fef3c7\"},\"posterUrl\":\"/posters/lat-mat-7-mot-dieu-uoc.jpg\",\"backdropUrl\":\"/backdrops/lat-mat-7-mot-dieu-uoc.jpg\",\"trailerId\":\"QdtPQ0wV53M\",\"id\":4,\"createdAt\":\"2026-05-08T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('40#39', '40', 'Cám', 'cam', 'now_showing', '2026-10-29', 39, '{\"title\":\"Cám\",\"slug\":\"cam\",\"tagline\":\"Cổ tích đẹp nhất là cổ tích bị bỏ quên.\",\"description\":\"Cám sinh ra với khuôn mặt dị dạng do lời nguyền truyền qua nhiều thế hệ, bị cha xem là vết nhơ và đày xuống nhà sau sống như người hầu. Trong khi chị cùng cha khác mẹ là Tấm được nuông chiều, lòng căm thù trong Cám ngày một lớn.\",\"director\":\"Trần Hữu Tấn\",\"cast\":[\"Lâm Thanh Mỹ\",\"Rima Thanh Vy\",\"Thuý Diễm\",\"Trần Doãn Hoàng\",\"Ngô Hải Nam\"],\"genres\":[\"Kinh dị\",\"Giả tượng\",\"Bí ẩn\",\"Giật gân\"],\"duration\":122,\"releaseDate\":\"2026-10-29\",\"language\":\"Tiếng Việt\",\"age\":\"T18\",\"rating\":9,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#ef4444\",\"via\":\"#7f1d1d\",\"to\":\"#0c0a09\",\"accent\":\"#fecaca\"},\"posterUrl\":\"/posters/cam.jpg\",\"backdropUrl\":\"/backdrops/cam.jpg\",\"trailerId\":\"_8qUFEmPQbc\",\"id\":40,\"createdAt\":\"2026-06-13T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('41#40', '41', 'Nhà Gia Tiên', 'nha-gia-tien', 'now_showing', '2026-10-30', 40, '{\"title\":\"Nhà Gia Tiên\",\"slug\":\"nha-gia-tien\",\"tagline\":\"Ông bà không đi đâu cả.\",\"description\":\"Nhà Gia Tiên xoay quanh câu chuyện đa góc nhìn về các thế hệ trong một gia đình, với hai nhân vật chính là Gia Minh và Mỹ Tiên. Về căn nhà gia tiên để quay video “triệu view”, Mỹ Tiên – nhà sáng tạo nội dung thế hệ Z không tin tâm linh – bất ngờ nhìn thấy Gia Minh.\",\"director\":\"Huỳnh Lập\",\"cast\":[\"Huỳnh Lập\",\"Phương Mỹ Chi\",\"Hạnh Thúy\",\"Puka\",\"Huỳnh Đông\"],\"genres\":[\"Kinh dị\",\"Hài\",\"Gia đình\",\"Chính kịch\"],\"duration\":117,\"releaseDate\":\"2026-10-30\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":7.6,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#f59e0b\",\"via\":\"#78350f\",\"to\":\"#1c0a0a\",\"accent\":\"#fde68a\"},\"posterUrl\":\"/posters/nha-gia-tien.jpg\",\"backdropUrl\":\"/backdrops/nha-gia-tien.jpg\",\"trailerId\":\"hXGozmNBwt4\",\"id\":41,\"createdAt\":\"2026-06-14T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('42#41', '42', 'Bộ Tứ Báo Thủ', 'bo-tu-bao-thu', 'now_showing', '2026-10-31', 41, '{\"title\":\"Bộ Tứ Báo Thủ\",\"slug\":\"bo-tu-bao-thu\",\"tagline\":\"Bốn người, một phi vụ, cả rổ rắc rối.\",\"description\":\"Bộ tứ báo thủ gồm Chét-Xi-Cà, Dì Bốn, Cậu Mười Một và Con Kiều xuất hiện cùng phi vụ báo thế kỷ. Kế hoạch tiếp theo là ở Đà Lạt, và bốn báo thủ quyết định quậy Tết tung nóc.\",\"director\":\"Trấn Thành\",\"cast\":[\"Quốc Anh\",\"Trần Tiểu Vy\",\"Kỳ Duyên\",\"Trấn Thành\",\"Uyển Ân\"],\"genres\":[\"Hài\",\"Hành động\",\"Tình cảm\"],\"duration\":133,\"releaseDate\":\"2026-10-31\",\"language\":\"Tiếng Việt\",\"age\":\"T13\",\"rating\":5.8,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#f97316\",\"via\":\"#b45309\",\"to\":\"#1c1917\",\"accent\":\"#fed7aa\"},\"posterUrl\":\"/posters/bo-tu-bao-thu.jpg\",\"backdropUrl\":\"/backdrops/bo-tu-bao-thu.jpg\",\"trailerId\":\"zKMOgOWn8lQ\",\"id\":42,\"createdAt\":\"2026-06-15T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('5#4', '5', 'Trạng Tí Phiêu Lưu Ký', 'trang-ti-phieu-luu-ky', 'now_showing', '2026-10-20', 4, '{\"title\":\"Trạng Tí Phiêu Lưu Ký\",\"slug\":\"trang-ti-phieu-luu-ky\",\"tagline\":\"Bốn đứa trẻ, một hành trình không tưởng.\",\"description\":\"Chuyến phiêu lưu ngoài sức tưởng tượng của bộ tứ Tí – Sửu – Dần – Mẹo khi cả nhóm phải vượt qua nhiều thử thách để khám phá bí ẩn về cha Tí. Trên hành trình, bốn đứa trẻ bị sơn tặc bắt cóc và buộc phải đối đầu với một âm mưu không thể lường trước.\",\"director\":\"Phan Gia Nhật Linh\",\"cast\":[\"Huỳnh Hữu Khang\",\"Mona Bảo Tiên\",\"Vương Hoàng Long\",\"Trần Đức Anh\",\"Trung Dân\"],\"genres\":[\"Phiêu lưu\",\"Giả tượng\",\"Gia đình\",\"Hài\"],\"duration\":110,\"releaseDate\":\"2026-10-20\",\"language\":\"Tiếng Việt\",\"age\":\"P\",\"rating\":7,\"status\":\"now_showing\",\"featured\":true,\"art\":{\"from\":\"#facc15\",\"via\":\"#a16207\",\"to\":\"#1c1917\",\"accent\":\"#fef9c3\"},\"posterUrl\":\"/posters/trang-ti-phieu-luu-ky.jpg\",\"backdropUrl\":\"/backdrops/trang-ti-phieu-luu-ky.jpg\",\"trailerId\":\"3aW_ofzDiZo\",\"id\":5,\"createdAt\":\"2026-05-09T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('6#5', '6', 'Chuyện Ma Gần Nhà', 'chuyen-ma-gan-nha', 'now_showing', '2026-10-16', 5, '{\"title\":\"Chuyện Ma Gần Nhà\",\"slug\":\"chuyen-ma-gan-nha\",\"tagline\":\"Chuyện ma ở ngay cạnh nhà.\",\"description\":\"Tác phẩm đầu tiên trong vũ trụ kinh dị Việt Nam, lấy cảm hứng từ những truyền thuyết đô thị và câu chuyện ma trong dân gian. Phim mang màu sắc u ám, quỷ dị, đan cài văn hoá và tín ngưỡng của người Việt vào từng khung hình.\",\"director\":\"Trần Hữu Tấn\",\"cast\":[\"Khả Như\",\"Mạc Can\",\"Vân Trang\",\"Thanh Trực\",\"Lê Bê La\"],\"genres\":[\"Kinh dị\",\"Giật gân\",\"Bí ẩn\"],\"duration\":110,\"releaseDate\":\"2026-10-16\",\"language\":\"Tiếng Việt\",\"age\":\"T16\",\"rating\":5.5,\"status\":\"now_showing\",\"featured\":true,\"art\":{\"from\":\"#22d3ee\",\"via\":\"#0e7490\",\"to\":\"#020617\",\"accent\":\"#a5f3fc\"},\"posterUrl\":\"/posters/chuyen-ma-gan-nha.jpg\",\"backdropUrl\":\"/backdrops/chuyen-ma-gan-nha.jpg\",\"trailerId\":\"XveLprAPXoE\",\"id\":6,\"createdAt\":\"2026-05-10T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('7#6', '7', 'Lôi Báo', 'loi-bao', 'now_showing', '2026-10-12', 6, '{\"title\":\"Lôi Báo\",\"slug\":\"loi-bao\",\"tagline\":\"Đổi thân xác, đổi cả số phận.\",\"description\":\"Tâm là một hoạ sĩ truyện tranh có cuộc sống hạnh phúc bên vợ và con trai. Khi phát hiện mình bị ung thư phổi giai đoạn cuối, anh nhận lời đổi đầu sang một cơ thể mới. Sau ca phẫu thuật, anh không chỉ khỏi bệnh mà còn sở hữu năng lực phi thường.\",\"director\":\"Victor Vũ\",\"cast\":[\"Cường Seven\",\"Nhã Phương\",\"Simba A Pù\",\"Hoàng Sơn\",\"Quách Ngọc Ngoan\"],\"genres\":[\"Hành động\",\"Khoa học viễn tưởng\",\"Phiêu lưu\",\"Chính kịch\"],\"duration\":90,\"releaseDate\":\"2026-10-12\",\"language\":\"Tiếng Việt\",\"age\":\"T13\",\"rating\":5.3,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#38bdf8\",\"via\":\"#1d4ed8\",\"to\":\"#020617\",\"accent\":\"#bae6fd\"},\"posterUrl\":\"/posters/loi-bao.jpg\",\"backdropUrl\":\"/backdrops/loi-bao.jpg\",\"trailerId\":\"f_pmSmrR0VU\",\"id\":7,\"createdAt\":\"2026-05-11T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('8#7', '8', 'Wolfoo và Hòn Đảo Kỳ Bí', 'wolfoo-hon-dao-ky-bi', 'now_showing', '2026-10-22', 7, '{\"title\":\"Wolfoo và Hòn Đảo Kỳ Bí\",\"slug\":\"wolfoo-hon-dao-ky-bi\",\"tagline\":\"Lạc vào Linh Giới, tìm em bằng mọi giá.\",\"description\":\"Wolfoo 8 tuổi và em gái Lucy bị hút vào một chiếc dây chuyền, lạc đến Linh Giới – thế giới kỳ diệu nơi hai anh em bị chia tách. Trong hành trình tìm em, Wolfoo bị cuốn vào cuộc chiến chống lại binh đoàn quỷ dữ do chú quỷ Bane cai trị.\",\"director\":\"Phan Thị Thơ\",\"cast\":[\"Sony Minh Hiếu\",\"Đạt Phi\",\"Như Ý\"],\"genres\":[\"Hoạt hình\",\"Phiêu lưu\",\"Giả tượng\",\"Gia đình\"],\"duration\":100,\"releaseDate\":\"2026-10-22\",\"language\":\"Tiếng Việt\",\"age\":\"P\",\"rating\":0,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#4ade80\",\"via\":\"#15803d\",\"to\":\"#052e16\",\"accent\":\"#dcfce7\"},\"posterUrl\":\"/posters/wolfoo-hon-dao-ky-bi.jpg\",\"backdropUrl\":\"/backdrops/wolfoo-hon-dao-ky-bi.jpg\",\"trailerId\":\"JBh7SlUwPUg\",\"id\":8,\"createdAt\":\"2026-05-12T01:00:00.000Z\"}', '2026-11-01 10:50:31'),
('9#8', '9', 'Nhà Bà Nữ', 'nha-ba-nu', 'now_showing', '2026-10-24', 8, '{\"title\":\"Nhà Bà Nữ\",\"slug\":\"nha-ba-nu\",\"tagline\":\"Ai cũng có lỗi, nhưng ai cũng nghĩ mình là nạn nhân.\",\"description\":\"Ba thế hệ gia đình bà Nữ sống chung trong một ngôi nhà. Bà Nữ một tay cáng đáng mọi việc, nổi tiếng với quán bánh canh cua và khét tiếng kiểm soát cuộc sống của con cái. Mọi thứ thay đổi khi cô con gái út si mê một chàng trai nhà giàu.\",\"director\":\"Trấn Thành\",\"cast\":[\"Uyển Ân\",\"Song Luân\",\"Lê Giang\",\"Khả Như\",\"Trấn Thành\"],\"genres\":[\"Hài\",\"Gia đình\",\"Chính kịch\",\"Tâm lý\"],\"duration\":103,\"releaseDate\":\"2026-10-24\",\"language\":\"Tiếng Việt\",\"age\":\"T13\",\"rating\":6,\"status\":\"now_showing\",\"featured\":false,\"art\":{\"from\":\"#fb7185\",\"via\":\"#9f1239\",\"to\":\"#1f0a12\",\"accent\":\"#fecdd3\"},\"posterUrl\":\"/posters/nha-ba-nu.jpg\",\"backdropUrl\":\"/backdrops/nha-ba-nu.jpg\",\"trailerId\":\"IkaP0KJWTsQ\",\"id\":9,\"createdAt\":\"2026-05-13T01:00:00.000Z\"}', '2026-11-01 10:50:31');
INSERT INTO `news` (`row_key`, `id`, `title`, `slug`, `status`, `published_at`, `ord`, `data`, `updated_at`) VALUES
('1#0', '1', 'PXU Cinema ra mắt phòng Gold Class tại Royal City', 'ra-mat-phong-gold-class', 'published', '2026-10-29T11:23:02.255Z', 0, '{\"id\":1,\"title\":\"PXU Cinema ra mắt phòng Gold Class tại Royal City\",\"slug\":\"ra-mat-phong-gold-class\",\"excerpt\":\"Trải nghiệm ghế êm, phục vụ tại chỗ và không gian riêng tư cho những buổi hẹn đặc biệt.\",\"body\":\"PXU Cinema chính thức khai trương phòng Gold Class tại PXU Cinema Royal City với 104 chỗ ngồi, ghế da cao cấp và dịch vụ phục vụ tại chỗ. Khách hàng Gold Class được ưu tiên check-in riêng và nhận combo bắp nước tại ghế.\",\"imageTone\":\"#fbbf24\",\"tag\":\"Tin rạp\",\"publishedAt\":\"2026-10-29T11:23:02.255Z\",\"status\":\"published\"}', '2026-11-01 11:23:02'),
('2#1', '2', 'Ưu đãi 50K cho thành viên khi đặt vé online', 'uu-dai-50k-thanh-vien', 'published', '2026-10-30T11:23:02.255Z', 1, '{\"id\":2,\"title\":\"Ưu đãi 50K cho thành viên khi đặt vé online\",\"slug\":\"uu-dai-50k-thanh-vien\",\"excerpt\":\"Nhập mã PXU50K cho đơn từ 300.000đ, áp dụng đến hết tháng này.\",\"body\":\"Chương trình áp dụng cho khách hàng đặt vé trực tuyến tại PXU Cinema, không áp dụng đồng thời với các chương trình giảm giá khác. Mỗi tài khoản sử dụng 1 lần.\",\"imageTone\":\"#ff6600\",\"tag\":\"Khuyến mãi\",\"publishedAt\":\"2026-10-30T11:23:02.255Z\",\"status\":\"published\"}', '2026-11-01 11:23:02'),
('3#2', '3', 'Hướng dẫn nhận bắp nước khi đặt combo online', 'huong-dan-nhan-bap-nuoc', 'published', '2026-10-27T11:23:02.255Z', 2, '{\"id\":3,\"title\":\"Hướng dẫn nhận bắp nước khi đặt combo online\",\"slug\":\"huong-dan-nhan-bap-nuoc\",\"excerpt\":\"Xuất trình mã đơn tại quầy bắp nước, không cần check-in như vé.\",\"body\":\"Sau khi đặt vé và combo online, bạn nhận được mã QR đơn hàng trong mục \\\"Vé của tôi\\\". Tại rạp, đến quầy bắp nước, xuất trình mã này để nhận combo. Combo chỉ nhận một lần và không hoàn tiền sau khi nhận.\",\"imageTone\":\"#22c55e\",\"tag\":\"Hướng dẫn\",\"publishedAt\":\"2026-10-27T11:23:02.255Z\",\"status\":\"published\"}', '2026-11-01 11:23:02');
