('17#16', '17', 'u-customer', 'payment', 0, '2026-11-06T02:06:48.441Z', 16, '{\"id\":17,\"userId\":\"u-customer\",\"title\":\"Đã nhận biên lai\",\"body\":\"PXU Cinema đã nhận biên lai cho đơn PXU-261106-EE4GDJ. Chúng tôi sẽ xác nhận trong thời gian sớm nhất.\",\"type\":\"payment\",\"read\":false,\"createdAt\":\"2026-11-06T02:06:48.441Z\",\"link\":\"/thanh-toan/PXU-261106-EE4GDJ\"}', '2026-11-06 02:06:48'),
('2#1', '2', 'u-admin', 'payment', 0, '2026-11-01T11:17:02.255Z', 1, '{\"id\":2,\"userId\":\"u-admin\",\"title\":\"Có biên lai mới chờ duyệt\",\"body\":\"3 biên lai đang chờ xác nhận thanh toán. Ưu tiên xử lý đơn chờ lâu nhất.\",\"type\":\"payment\",\"read\":false,\"createdAt\":\"2026-11-01T11:17:02.255Z\",\"link\":\"/admin/duyet-bien-lai\"}', '2026-11-06 02:06:48'),
('2#2', '2', 'u-admin', 'system', 0, '2026-11-01T10:43:02.255Z', 2, '{\"id\":2,\"userId\":\"u-admin\",\"title\":\"Cảnh báo tồn kho\",\"body\":\"Nachos Sốt Phô Mai đã hết hàng. Cập nhật kho để tiếp tục bán.\",\"type\":\"system\",\"read\":false,\"createdAt\":\"2026-11-01T10:43:02.255Z\",\"link\":\"/admin/combo\"}', '2026-11-06 02:06:48'),
