INSERT INTO `reviews` (`row_key`, `id`, `movie_id`, `user_id`, `rating`, `visible`, `ord`, `data`, `updated_at`) VALUES
('1#0', '1', 19, 'u-customer', 9, 1, 0, '{\"id\":1,\"movieId\":19,\"userId\":\"u-customer\",\"userName\":\"Nguyễn Minh Anh\",\"rating\":9,\"comment\":\"Hình ảnh và âm thanh rất tốt, phòng chiếu sạch và nhân viên thân thiện. Sẽ quay lại!\",\"visible\":true,\"createdAt\":\"2026-10-31T23:23:02.255Z\"}', '2026-11-01 11:23:02'),
('2#1', '2', 2, 'u-c3', 9, 1, 1, '{\"id\":2,\"movieId\":2,\"userId\":\"u-c3\",\"userName\":\"Đặng Khánh Linh\",\"rating\":9,\"comment\":\"Bối cảnh Hà Nội 60 ngày đêm rất đẹp, diễn xuất tốt và cảm xúc. Một bộ phim Việt đáng xem.\",\"visible\":true,\"createdAt\":\"2026-10-30T11:23:02.255Z\"}', '2026-11-01 11:23:02'),
('3#2', '3', 5, 'u-c2', 8, 1, 2, '{\"id\":3,\"movieId\":5,\"userId\":\"u-c2\",\"userName\":\"Võ Hoàng Nam\",\"rating\":8,\"comment\":\"Rất phù hợp cho gia đình có trẻ nhỏ. Con mình thích nhất bộ tứ Tí – Sửu – Dần – Mẹo.\",\"visible\":true,\"createdAt\":\"2026-10-28T11:23:02.255Z\"}', '2026-11-01 11:23:02'),
('4#3', '4', 6, 'u-c6', 9, 0, 3, '{\"id\":4,\"movieId\":6,\"userId\":\"u-c6\",\"userName\":\"Đỗ Anh Khoa\",\"rating\":9,\"comment\":\"Kinh dị dân gian Việt Nam làm rất có không khí. Nhớ mang CCCD vì phim T16.\",\"visible\":false,\"createdAt\":\"2026-10-31T11:23:02.255Z\"}', '2026-11-01 11:23:02');
