INSERT INTO `static_pages` (`row_key`, `id`, `slug`, `title`, `ord`, `data`, `updated_at`) VALUES
('bao-mat#2', 'bao-mat', 'bao-mat', 'Chính sách bảo mật', 2, '{\"slug\":\"bao-mat\",\"title\":\"Chính sách bảo mật\",\"body\":\"PXU Cinema chỉ thu thập thông tin cần thiết cho việc đặt vé và chăm sóc khách hàng. Dữ liệu được lưu trữ an toàn, không chia sẻ cho bên thứ ba ngoài đơn vị thanh toán và đơn vị vận chuyển thông báo.\"}', '2026-10-30 01:16:55'),
('chinh-sach-hoan-huy#1', 'chinh-sach-hoan-huy', 'chinh-sach-hoan-huy', 'Chính sách hoàn hủy', 1, '{\"slug\":\"chinh-sach-hoan-huy\",\"title\":\"Chính sách hoàn hủy\",\"body\":\"Khách hàng có thể tự hủy đơn đang giữ ghế. Đơn đã thanh toán chỉ được hoàn theo chính sách của rạp: hủy trước giờ chiếu tối thiểu 2 giờ, mức hoàn do quản lý rạp quyết định. Vé đã sử dụng không thể hủy hoặc hoàn.\"}', '2026-10-30 01:16:55'),
('dieu-khoan#0', 'dieu-khoan', 'dieu-khoan', 'Điều khoản sử dụng', 0, '{\"slug\":\"dieu-khoan\",\"title\":\"Điều khoản sử dụng\",\"body\":\"Khi sử dụng dịch vụ của PXU Cinema, bạn đồng ý với các điều khoản về đặt vé, thanh toán, hoàn hủy và bảo mật thông tin cá nhân theo quy định pháp luật hiện hành, bao gồm Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân.\"}', '2026-10-30 01:16:55'),
('faq#3', 'faq', 'faq', 'Câu hỏi thường gặp', 3, '{\"slug\":\"faq\",\"title\":\"Câu hỏi thường gặp\",\"body\":\"Tôi có thể đổi ghế sau khi thanh toán? — Có, nếu còn ít nhất 30 phút trước giờ chiếu và ghế mới có giá bằng hoặc thấp hơn. Tôi cần mang gì khi nhận vé ưu đãi? — Vui lòng mang giấy tờ chứng minh (HSSV, CCCD) để nhân viên kiểm tra tại cửa phòng.\"}', '2026-10-30 01:16:55'),
('quy-che-rap#4', 'quy-che-rap', 'quy-che-rap', 'Quy chế rạp', 4, '{\"slug\":\"quy-che-rap\",\"title\":\"Quy chế rạp\",\"body\":\"Không mang thức ăn từ bên ngoài vào phòng chiếu. Vui lòng giữ trật tự, tắt chuông điện thoại. Phim T16/T18 yêu cầu xuất trình giấy tờ hợp lệ. Trẻ em dưới 13 tuổi cần người bảo hộ khi xem phim nhãn K.\"}', '2026-10-30 01:16:55');
